const searchOrgMembers = `-- name: SearchOrgMembers :many
SELECT u.id, u.email, u.display_name, u.avatar_url
FROM memberships m
JOIN users u ON u.id = m.user_id AND u.deleted_at IS NULL
WHERE m.org_id = $1 AND u.is_active
  -- See SuggestTicketRefs: the caller's text is a literal substring, so ` + "`" + `%` + "`" + `
  -- and ` + "`" + `_` + "`" + ` are escaped to match themselves rather than act as wildcards
  -- (backslash is PostgreSQL's default LIKE escape, so it is doubled first).
  -- An empty query still matches every member — '%%' — which is intended.
  AND (u.display_name ILIKE '%' || replace(replace(replace($2::text, '\', '\\'), '%', '\%'), '_', '\_') || '%'
       OR u.email ILIKE '%' || replace(replace(replace($2::text, '\', '\\'), '%', '\%'), '_', '\_') || '%')
ORDER BY u.display_name ASC, u.id ASC
LIMIT 20
`

type SearchOrgMembersParams struct {
	OrgID uuid.UUID `json:"org_id"`
	Query string    `json:"query"`
}

type SearchOrgMembersRow struct {
	ID          uuid.UUID `json:"id"`
	Email       string    `json:"email"`
	DisplayName string    `json:"display_name"`
	AvatarUrl   *string   `json:"avatar_url"`
}

// The person picker: name-or-email search over active org members. Bounded
// result set; one query.
func (q *Queries) SearchOrgMembers(ctx context.Context, arg SearchOrgMembersParams) ([]SearchOrgMembersRow, error) {
	rows, err := q.db.Query(ctx, searchOrgMembers, arg.OrgID, arg.Query)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SearchOrgMembersRow{}
	for rows.Next() {
		var i SearchOrgMembersRow
		if err := rows.Scan(
			&i.ID,
			&i.Email,
			&i.DisplayName,
			&i.AvatarUrl,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

